 "content": "def transform(grid):
    """Restore the two cyclic bands, including the staircase boundary."""
    h, w = len(grid), len(grid[0])
    colors = sorted({x for row in grid for x in row if x})
    upper_start = grid[0][0]
    lower_start = next((row[0] for row in grid[1:] if row[0] != 0), upper_start)

    def cycle_from(start):
        i = colors.index(start)
        return colors[i:] + colors[:i]

    upper, lower = cycle_from(upper_start), cycle_from(lower_start)
    result = []
    for r in range(h):
        row = []
        for c in range(w):
            if c < r:
                row.append(lower[c % len(lower)])
            elif c == r and r > 0:
                row.append(lower[(r - 1) % len(lower)])
            else:
                row.append(upper[c % len(upper)])
        result.append(row)
    return result
